"""Recognize the reward choice overlay before gameplay input is allowed."""
import base64
import cv2
import numpy as np
_HEADER=cv2.imdecode(np.frombuffer(base64.b64decode(''),np.uint8),cv2.IMREAD_GRAYSCALE)
def is_reward_choice(frame):
    if frame is None or frame.size == 0:
        return False
    small=cv2.resize(frame,(640,360),interpolation=cv2.INTER_AREA)
    mask=(small.min(axis=2)>225).astype(np.uint8)*255
    region=mask[10:65,135:505]
    score=cv2.matchTemplate(region,_HEADER,cv2.TM_CCOEFF_NORMED)
    return bool(cv2.minMaxLoc(score)[1] >= 0.85)
